SELECT * FROM OPENQUERY([DELTEK_VP], 'SELECT LEFT(WBS1, 2) AS Pfx, ChargeType, COUNT(*) AS N, SUM(CASE WHEN LTRIM(RTRIM(ISNULL(ProposalWBS1, ''''))) <> '''' THEN 1 ELSE 0 END) AS HasProposalWBS1, SUM(CASE WHEN LTRIM(RTRIM(ISNULL(PreAwardWBS1, ''''))) <> '''' THEN 1 ELSE 0 END) AS HasPreAwardWBS1, SUM(CASE WHEN LTRIM(RTRIM(ISNULL(OpportunityID, ''''))) <> '''' THEN 1 ELSE 0 END) AS HasOpportunityID, SUM(CASE WHEN LTRIM(RTRIM(ISNULL(SiblingWBS1, ''''))) <> '''' THEN 1 ELSE 0 END) AS HasSiblingWBS1, SUM(CASE WHEN LTRIM(RTRIM(ISNULL(ClosedReason, ''''))) <> '''' THEN 1 ELSE 0 END) AS HasClosedReason FROM [C0000052267P_1_KOR00000000].dbo.PR WHERE LTRIM(RTRIM(ISNULL(WBS2, ''''))) = '''' GROUP BY LEFT(WBS1, 2), ChargeType') FOR JSON PATH
